compile.workshop:
variables {
    global:
        0: g
        1: A
    player:
        0: foo
        1: B
}

rule ("optimized") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Modify Global Variable(g, Add, 1);
        Modify Global Variable(g, Subtract, 1);
        Modify Global Variable(g, Multiply, 2);
        Modify Global Variable(g, Divide, 2);
        Modify Global Variable(g, Modulo, 2);
        Modify Global Variable(g, Raise To Power, 2);
        Modify Global Variable At Index(A, 0, Add, 1);
        Modify Global Variable At Index(A, 1, Subtract, 1);
        Modify Global Variable At Index(A, 1, Multiply, 2);
        Modify Global Variable At Index(A, 1, Divide, 2);
        Modify Global Variable At Index(A, 1, Modulo, 2);
        Modify Global Variable At Index(A, 1, Raise To Power, 2);
        Modify Player Variable(Event Player, foo, Add, 1);
        Modify Player Variable(Event Player, foo, Subtract, 1);
        Modify Player Variable(Event Player, foo, Multiply, 2);
        Modify Player Variable(Event Player, foo, Divide, 2);
        Modify Player Variable(Event Player, foo, Modulo, 2);
        Modify Player Variable(Event Player, foo, Raise To Power, 2);
        Modify Player Variable At Index(Event Player, B, 1, Add, 1);
        Set Global Variable At Index(A, 1, Append To Array(Append To Array(Array Slice(Value In Array(Global.A, 1), 0, 2), Array(Add(Value In Array(Value In Array(Global.A, 1), 2), 1))), Array Slice(Value In Array(Global.A, 1), Add(2, 1), 999999999999)));
        Set Global Variable(g, Add(1, Global.g));
        Modify Global Variable At Index(A, 1, Add, 1);
        Modify Global Variable At Index(A, 1, Add, 1);
        Modify Global Variable(g, Add, 1);
        Modify Global Variable At Index(A, 1, Add, 1);
        Modify Player Variable(Event Player, foo, Add, 1);
        Modify Player Variable At Index(Event Player, B, 1, Add, 1);
        Set Global Variable At Index(A, 1, Append To Array(Append To Array(Array Slice(Value In Array(Global.A, 1), 0, 1), Array(Add(Value In Array(Value In Array(Global.A, 1), 1), 1))), Array Slice(Value In Array(Global.A, 1), Add(1, 1), 999999999999)));
    }
}

